Players.Raelity911.PlayerGui.TutorialUi.Main.Container.Topbar.Title | Cara Bermain
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.Topbar.Ikon | 📋
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.Topbar.Subjudul | Panduan & fitur baru
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.2 | Selamat datang di Juragan Kost! Ikuti langkah berikut agar cepat mahir.
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.1 | 📖  Tutorial
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.4 | 🏠  1. Spawn Rumah
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.5 | Buka menu <b>Shop</b> lalu beli dan letakkan rumah pertamamu di zona yang tersedia.
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.7 | 🖱️  2. Upgrade & Pindah Bangunan
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.8 | Klik <b>2 kali</b> pada bangunan untuk membuka panel Upgrade dan Move. Gunakan Upgrade untuk naik level, atau Move untuk memindahkan posisi bangunan.
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.91 | 🧹  3. Bersihkan Rumah
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.92 | Bersihkan kamar / rumah yang kotor agar NPC (penyewa) mau datang dan menempatinya.
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.94 | ✅  4. Acc Notif NPC
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.95 | Ketika muncul notifikasi NPC ingin menyewa, segera tekan tombol <b>Accept</b> untuk mengkonfirmasi dan mendapatkan penghasilan.
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.98 | 💼  5. Mode Pekerja (Bantu Teman)
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.99 | Klik ikon <b>Koper</b> di layar untuk beralih ke mode Pekerja.
Setelah itu, datangi teman dan tekan tombol <b>Minta Pekerjaan</b> agar bisa membantu mengelola properti mereka.
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.101 | 🎁  6. Gift Domba
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.102 | Sekarang bisa gift Domba ke player lain! Pergi ke <b>Kandang</b>, lalu tekan <b>ProximityPrompt (E)</b> di sekitar kandang. Akan muncul UI daftar dombamu, lalu tekan <b>Gift</b> atau kirim ke player yang ada di server.
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.104 | 📦  7. System Gudang
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.105 | Ada fitur baru <b>Gudang</b>! Gudang ini untuk menyimpan barang-barangmu dari zona ke gudang. Caranya: <b>Klik 2x</b> pada benda yang mau disimpan, lalu klik <b>Cabut</b>. Barang akan pindah ke gudang.
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.106 | Barang di gudang bisa <b>dijual</b> dengan potongan 50% dari harga asli, dan bisa juga <b>di-gift</b> ke teman kalian!
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.108 | <b>8. Restock Shop</b>
Players.Raelity911.PlayerGui.TutorialUi.Main.Container.ScrollingFrame.109 | Sekarang Shop IndoKost di jam <b>12 malam sampai jam 6 pagi</b> akan restok. Jadi kalo butuh dekorasi, bisa saling komunikasi antar player untuk jual beli barang!
